/**
 * scripts/generate-icons.js
 * Pure Node.js high-fidelity PNG icon generator for Cinejoy webOS TV
 * Zero external npm dependencies. Uses native zlib and Buffer.
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

// Precomputed CRC-32 table for PNG chunk checksumming
const crcTable = new Uint32Array(256);
for (let n = 0; n < 256; n++) {
  let c = n;
  for (let k = 0; k < 8; k++) c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
  crcTable[n] = c;
}

function crc32(buf) {
  let crc = 0xFFFFFFFF;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ crcTable[(crc ^ buf[i]) & 0xFF];
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function createPng(width, height, sampleFn) {
  const scale = width / 80;
  const subSteps = 4; // 4x4 supersampling for anti-aliased vector edges
  const totalSamples = subSteps * subSteps;

  const rowStride = 1 + width * 4;
  const raw = Buffer.alloc(height * rowStride);

  for (let y = 0; y < height; y++) {
    const rowOffset = y * rowStride;
    raw[rowOffset] = 0; // Filter method: 0 (None)
    for (let x = 0; x < width; x++) {
      let rSum = 0, gSum = 0, bSum = 0, aSum = 0;
      for (let sy = 0; sy < subSteps; sy++) {
        for (let sx = 0; sx < subSteps; sx++) {
          const subX = x + (sx + 0.5) / subSteps;
          const subY = y + (sy + 0.5) / subSteps;
          const [sr, sg, sb, sa] = sampleFn(subX, subY, scale);
          rSum += (sr * sa) / 255;
          gSum += (sg * sa) / 255;
          bSum += (sb * sa) / 255;
          aSum += sa;
        }
      }
      const avgA = aSum / totalSamples;
      const avgR = avgA > 0 ? (rSum / totalSamples) * (255 / avgA) : 0;
      const avgG = avgA > 0 ? (gSum / totalSamples) * (255 / avgA) : 0;
      const avgB = avgA > 0 ? (bSum / totalSamples) * (255 / avgA) : 0;

      const pxOffset = rowOffset + 1 + x * 4;
      raw[pxOffset] = Math.round(avgR);
      raw[pxOffset + 1] = Math.round(avgG);
      raw[pxOffset + 2] = Math.round(avgB);
      raw[pxOffset + 3] = Math.round(avgA);
    }
  }

  const idatData = zlib.deflateSync(raw, { level: 9 });

  function makeChunk(type, data) {
    const typeBuf = Buffer.from(type, 'ascii');
    const lenBuf = Buffer.alloc(4);
    lenBuf.writeUInt32BE(data.length, 0);
    const body = Buffer.concat([typeBuf, data]);
    const crcBuf = Buffer.alloc(4);
    crcBuf.writeUInt32BE(crc32(body), 0);
    return Buffer.concat([lenBuf, body, crcBuf]);
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(width, 0);
  ihdr.writeUInt32BE(height, 4);
  ihdr[8] = 8; // 8-bit depth
  ihdr[9] = 6; // Color type: RGBA
  ihdr[10] = 0; // Deflate compression
  ihdr[11] = 0; // Filter method
  ihdr[12] = 0; // Non-interlaced

  const sig = Buffer.from([0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);
  const ihdrChunk = makeChunk('IHDR', ihdr);
  const idatChunk = makeChunk('IDAT', idatData);
  const iendChunk = makeChunk('IEND', Buffer.alloc(0));

  return Buffer.concat([sig, ihdrChunk, idatChunk, iendChunk]);
}

function sampleCinejoyIcon(x, y, scale) {
  const BG_COLOR = [4, 18, 11, 255];       // #04120B
  const ACCENT_LIME = [149, 255, 80, 255]; // #95FF50
  const DOT_WHITE = [255, 255, 255, 255];  // #FFFFFF

  const pad = 4 * scale;
  const rw = 72 * scale;
  const rh = 72 * scale;
  const radius = 16 * scale;
  const borderWidth = 2.5 * scale;

  // Signed distance function for rounded rectangle
  function inRoundedRect(px, py, rx, ry, w, h, r) {
    if (px < rx || px > rx + w || py < ry || py > ry + h) return false;
    const innerLeft = rx + r;
    const innerRight = rx + w - r;
    const innerTop = ry + r;
    const innerBottom = ry + h - r;
    if (px >= innerLeft && px <= innerRight) return true;
    if (py >= innerTop && py <= innerBottom) return true;
    let dx = 0, dy = 0;
    if (px < innerLeft) dx = px - innerLeft;
    else if (px > innerRight) dx = px - innerRight;
    if (py < innerTop) dy = py - innerTop;
    else if (py > innerBottom) dy = py - innerBottom;
    return (dx * dx + dy * dy) <= (r * r);
  }

  // Point in triangle test
  function inTriangle(px, py, [x1, y1], [x2, y2], [x3, y3]) {
    const d1 = (px - x2) * (y1 - y2) - (x1 - x2) * (py - y2);
    const d2 = (px - x3) * (y2 - y3) - (x2 - x3) * (py - y3);
    const d3 = (px - x1) * (y3 - y1) - (x3 - x1) * (py - y1);
    const hasNeg = (d1 < 0) || (d2 < 0) || (d3 < 0);
    const hasPos = (d1 > 0) || (d2 > 0) || (d3 > 0);
    return !(hasNeg && hasPos);
  }

  // 1. Outside outer rounded container
  if (!inRoundedRect(x, y, pad, pad, rw, rh, radius)) {
    return [0, 0, 0, 0];
  }

  // 2. On rounded border
  const onInner = inRoundedRect(x, y, pad + borderWidth, pad + borderWidth, rw - 2 * borderWidth, rh - 2 * borderWidth, Math.max(0, radius - borderWidth));
  if (!onInner) {
    return ACCENT_LIME;
  }

  // 3. Top-right white accent dot
  const dotX = 58 * scale;
  const dotY = 22 * scale;
  const dotR = 4 * scale;
  if ((x - dotX) * (x - dotX) + (y - dotY) * (y - dotY) <= dotR * dotR) {
    return DOT_WHITE;
  }

  // 4. Directional Play Glyph
  const p1 = [28 * scale, 23 * scale];
  const p2 = [28 * scale, 57 * scale];
  const p3 = [58 * scale, 40 * scale];
  if (inTriangle(x, y, p1, p2, p3)) {
    return ACCENT_LIME;
  }

  // 5. Container background
  return BG_COLOR;
}

// Generate assets
const icon80 = createPng(80, 80, sampleCinejoyIcon);
const icon130 = createPng(130, 130, sampleCinejoyIcon);

// Write to app/ and root
const rootDir = path.resolve(__dirname, '..');
['.', 'app'].forEach(relDir => {
  const targetDir = path.resolve(rootDir, relDir);
  fs.writeFileSync(path.join(targetDir, 'icon.png'), icon80);
  fs.writeFileSync(path.join(targetDir, 'largeIcon.png'), icon130);
});
console.log('Successfully generated icon.png (80x80) and largeIcon.png (130x130) at root and app/');

