let spawnedServerProc = null;

// Probe local proxy daemon
function checkServerHealth(port = 8088) {
  return new Promise((resolve) => {
    const req = http.get(`http://127.0.0.1:${port}/health`, { timeout: 1000 }, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          resolve(json && json.status === 'ok');
        } catch (e) {
          resolve(false);
        }
      });
    });
    req.on('error', () => resolve(false));
    req.on('timeout', () => { req.destroy(); resolve(false); });
  });
}

async function ensureServerRunning() {
  const isHealthy = await checkServerHealth(8088);
  if (isHealthy) {
    console.log(`[MasterRunner] Streaming proxy already healthy on port 8088.`);
    return;
  }

  console.log(`[MasterRunner] Spawning background streaming proxy daemon (server/index.js)...`);
  spawnedServerProc = spawn('node', ['server/index.js'], {
    cwd: ROOT_DIR,
    stdio: 'ignore',
    detached: true
  });
  spawnedServerProc.unref();

  const start = Date.now();
  while (Date.now() - start < 6000) {
    await new Promise(r => setTimeout(r, 200));
    if (await checkServerHealth(8088)) {
      console.log(`[MasterRunner] Background streaming proxy successfully online (PID: ${spawnedServerProc.pid}).`);
      return;
    }
  }
  console.warn(`[MasterRunner] Warning: Proxy health check did not respond within 6s. Proceeding...`);
}

function stopSpawnedServer() {
  if (spawnedServerProc && spawnedServerProc.pid) {
    try {
      process.kill(-spawnedServerProc.pid, 'SIGTERM');
    } catch (e) {
      try { process.kill(spawnedServerProc.pid, 'SIGTERM'); } catch (e2) {}
    }
    spawnedServerProc = null;
  }
}

process.on('SIGINT', () => { stopSpawnedServer(); process.exit(130); });
