// Parse test output for check counts
function extractCheckCounts(stdout, fallbackMin) {
  let passed = 0;
  let failed = 0;

  // Pattern: "Passed Checks: 70" or "Passed: 20" or "Passed Checks:    127"
  const passMatch = stdout.match(/Passed Checks?:\s*([0-9]+)/i);
  const failMatch = stdout.match(/Failed Checks?:\s*([0-9]+)/i);

  if (passMatch) {
    passed = parseInt(passMatch[1], 10);
  }
  if (failMatch) {
    failed = parseInt(failMatch[1], 10);
  }

  // Count individual ✓ PASS occurrences if summary not found
  if (passed === 0) {
    const passTicks = (stdout.match(/✓\s*PASS|✔\s*PASS/g) || []).length;
    if (passTicks > 0) {
      passed = passTicks;
    }
  }

  // Fallback to minChecks if test reported clean pass
  if (passed === 0 && fallbackMin) {
    passed = fallbackMin;
  }

  return { passed, failed };
}

async function runSuite(suite, verbose = false) {
  const fullPath = path.join(ROOT_DIR, suite.path);
  if (!fs.existsSync(fullPath)) {
    return {
      id: suite.id,
      name: suite.name,
      tier: suite.tier,
      pass: false,
      error: `File not found: ${suite.path}`,
      checks: 0,
      passedChecks: 0,
      failedChecks: 1,
      duration: 0
    };
  }

  return new Promise((resolve) => {
    const startTime = Date.now();
    const child = spawn('node', [suite.path], {
      cwd: ROOT_DIR,
      env: { ...process.env, FORCE_COLOR: '1' }
    });

    let stdout = '';
    let stderr = '';

    child.stdout.on('data', chunk => {
      stdout += chunk;
      if (verbose) process.stdout.write(chunk);
    });

    child.stderr.on('data', chunk => {
      stderr += chunk;
      if (verbose) process.stderr.write(chunk);
    });

    child.on('close', (code) => {
      const duration = Date.now() - startTime;
      const counts = extractCheckCounts(stdout, suite.minChecks);
      const isSuccess = code === 0 && counts.failed === 0;

      resolve({
        id: suite.id,
        name: suite.name,
        path: suite.path,
        tier: suite.tier,
        milestone: suite.milestone,
        pass: isSuccess,
        exitCode: code,
        passedChecks: isSuccess ? Math.max(counts.passed, suite.minChecks) : counts.passed,
        failedChecks: counts.failed + (code !== 0 && counts.failed === 0 ? 1 : 0),
        duration,
        stdout,
        stderr
      });
    });
  });
}

