    timestamp: new Date().toISOString(),
    totalChecks: totalPassed + totalFailed,
    passedChecks: totalPassed,
    failedChecks: totalFailed,
    suitesRun: selectedSuites.length,
    suitesPassed: totalSuitesPassed,
    suitesFailed: totalSuitesFailed,
    tiers: tierSummary,
    results: suiteResults.map(r => ({
