    assert.strictEqual(pattern.test('app/js/app.js'), false);
  });

  await check('F12', 'B12.4', '--no-minify flag prevents script corruption by skipping uglify', () => {
    const pkg = JSON.parse(fs.readFileSync(path.join(ROOT_DIR, 'package.json'), 'utf8'));
    assert(pkg.scripts.package.includes('--no-minify'), 'package script must include --no-minify');
  });

  await check('F12', 'B12.5', 'Built package size budget verified (< 25MB)', () => {
    const maxBytes = 25 * 1024 * 1024;
    // App folder size calculation
    function getDirSize(dir) {
      let size = 0;
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const e of entries) {
        const full = path.join(dir, e.name);
        if (e.isDirectory()) size += getDirSize(full);
        else size += fs.statSync(full).size;
      }
      return size;
    }
    const appSize = getDirSize(path.join(ROOT_DIR, 'app'));
    assert(appSize < maxBytes, `App folder size (${appSize} bytes) must be < 25MB`);
  });

  // =========================================================================
  // F13 Boundary
  // =========================================================================
  await check('F13', 'B13.1', 'Runner handling failing test suite reports exit code 1 without unhandled crash', () => {
    function computeExitCode(failedCount) {
      return failedCount > 0 ? 1 : 0;
    }
    assert.strictEqual(computeExitCode(1), 1);
    assert.strictEqual(computeExitCode(0), 0);
  });

  await check('F13', 'B13.2', 'Timeout handling on hanging test suite process triggers cleanup', () => {
    function checkTimeout(elapsed, limit = 30000) {
      return elapsed > limit;
    }
    assert.strictEqual(checkTimeout(35000), true);
    assert.strictEqual(checkTimeout(5000), false);
  });

  await check('F13', 'B13.3', 'Invalid CLI flags handled gracefully with usage guidance', () => {
    function parseArgs(args) {
      const valid = ['--tier=', '--milestone=', '--bail', '--verbose', '--json'];
      for (const a of args) {
        if (!valid.some(v => a.startsWith(v))) {
          return { valid: false, unknown: a };
        }
      }
      return { valid: true };
    }
    assert.strictEqual(parseArgs(['--invalid-flag']).valid, false);
    assert.strictEqual(parseArgs(['--tier=1']).valid, true);
  });

  await check('F13', 'B13.4', 'Non-existent tier filter returns empty set and handles cleanly', () => {
    const allTiers = [1, 2, 3, 4, 5];
    const filtered = allTiers.filter(t => [99].includes(t));
    assert.strictEqual(filtered.length, 0);
  });

  await check('F13', 'B13.5', 'JSON summary output is valid parseable JSON', () => {
    const summary = {
      timestamp: new Date().toISOString(),
      passed: 70,
      failed: 0
    };
    const str = JSON.stringify(summary);
    const parsed = JSON.parse(str);
    assert.strictEqual(parsed.passed, 70);
  });

  // =========================================================================
  // F14 Boundary
  // =========================================================================
  await check('F14', 'B14.1', 'Invalid IP address string in configuration handled safely', () => {
    function isValidIpv4(ip) {
      const parts = ip.split('.');
      if (parts.length !== 4) return false;
      return parts.every(p => {
        const n = parseInt(p, 10);
        return String(n) === p && n >= 0 && n <= 255;
      });
    }
    assert.strictEqual(isValidIpv4('999.1.1.1'), false);
    assert.strictEqual(isValidIpv4('192.168.1.150'), true);
  });

  await check('F14', 'B14.2', 'Expired 50-hour session handling runbook documented in DEPLOYMENT.md', () => {
    const deployContent = fs.readFileSync(path.join(ROOT_DIR, 'DEPLOYMENT.md'), 'utf8');
    assert(deployContent.includes('50') && deployContent.includes('EXTEND'), 'DEPLOYMENT.md must document EXTEND for 50-hr session');
  });

  await check('F14', 'B14.3', 'Custom SSH port 9922 handling documented in DEPLOYMENT.md', () => {
    const deployContent = fs.readFileSync(path.join(ROOT_DIR, 'DEPLOYMENT.md'), 'utf8');
    assert(deployContent.includes('9922'), 'DEPLOYMENT.md must document port 9922');
  });

  await check('F14', 'B14.4', 'Missing private key recovery procedure verified in DEPLOYMENT.md', () => {
    const deployContent = fs.readFileSync(path.join(ROOT_DIR, 'DEPLOYMENT.md'), 'utf8');
    assert(deployContent.includes('ares-novacom') && deployContent.includes('--getkey'), 'DEPLOYMENT.md must document key download');
  });

  await check('F14', 'B14.5', 'Offline device error states cataloged in DEPLOYMENT.md diagnostic matrix', () => {
    const deployContent = fs.readFileSync(path.join(ROOT_DIR, 'DEPLOYMENT.md'), 'utf8');
    assert(deployContent.includes('Diagnostic & Troubleshooting Matrix') || deployContent.includes('Troubleshooting'), 'DEPLOYMENT.md must include troubleshooting matrix');
  });

  // =========================================================================
  // Summary & Exit Code
  // =========================================================================
  console.log(`\n${C.bold}${C.cyan}------------------------------------------------------------------------${C.reset}`);
  console.log(`  Tier 2 Boundary Checks Completed: ${totalChecks}`);
  console.log(`  Passed Checks:                    ${C.green}${C.bold}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:                    ${failedChecks > 0 ? `${C.red}${C.bold}${failedChecks}` : '0'}${C.reset}`);
  console.log(`${C.cyan}------------------------------------------------------------------------${C.reset}\n`);

  if (failedChecks > 0 || totalChecks < 70) {
    console.error(`${C.red}${C.bold}VERDICT: TIER 2 FAILED (${failedChecks} failures, ${totalChecks}/70 checks)${C.reset}\n`);
    process.exit(1);
  } else {
    console.log(`${C.green}${C.bold}VERDICT: TIER 2 PASSED (70/70 checks 100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  }
}

if (require.main === module) {
  runTier2();
}

module.exports = { runTier2 };

